import{z as d,x as n,o as A,c as i,q as E,j as l,D as r,d as o,s as t,S as c,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"原子指令：LR/SC 与 CAS","description":"","frontmatter":{"title":"原子指令：LR/SC 与 CAS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lr-sc-cas.md","filePath":"cs/lr-sc-cas.md","lastUpdated":1791063341000}'),C={name:"cs/lr-sc-cas.md"};function S(B,a,p,m,R,h){const s=n("Mermaid");return A(),i("div",null,[a[2]||(a[2]=E('<h1 id="原子指令-lr-sc-与-cas" tabindex="-1">原子指令：LR/SC 与 CAS <a class="header-anchor" href="#原子指令-lr-sc-与-cas" aria-label="Permalink to &quot;原子指令：LR/SC 与 CAS&quot;">​</a></h1><div class="epigraph"><p>多核要在内存上读改写而不夹缝：比较并交换一次给新值，或先保留加载再条件存储，失败则软件重试。</p><footer>—— 据 The RISC-V Instruction Set Manual；ARM ARM；Intel SDM；Herlihy and Shavit, The Art of Multiprocessor Programming 整理</footer></div><p><a href="/cs/arm-vs-riscv">上一课</a>把两家 RISC 放到同一家族。组成/体系结构的缓存一致性假定有原子原语。缺口是 ISA 如何暴露：<strong>CAS</strong>（x86 <code>lock cmpxchg</code>，ARM LSE）与 <strong>LR/SC</strong>（RISC-V <code>lr</code>/<code>sc</code>，ARM <code>ldxr</code>/<code>stxr</code>）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>lock; add</code> 一类 RMW 在缓存行上获取排他。CAS：读、比较、相等才写，返回旧值。LR/SC：<code>lr</code> 登记保留集，若中间无干扰 <code>sc</code> 成功。缺口不是 MESI 状态名，而是<strong>软件循环</strong>：CAS 失败重试；SC 失败重试；ABA 要用标签或 LL/SC 的保留语义缓解。</p><p><span class="marginnote">直觉类比：CAS 像抢座位——坐下前先核对一次「还是我想的那个空位」，被人抢先就退回重来；LR/SC 是先在座位上放一张「预留卡」（\\(\\mathrm{lr}\\)），回来时卡还在（\\(\\mathrm{sc}\\) 通过）才能坐，别人碰过卡就作废重排。</span></p><p>AMO（RISC-V <code>amoadd</code>）把常见 RMW 做成单指令，减少循环。x86 的 <code>lock</code> 前缀给读改写指令。</p><h3 id="lr-sc-不是「总线锁住到-sc」" tabindex="-1">LR/SC 不是「总线锁住到 sc」 <a class="header-anchor" href="#lr-sc-不是「总线锁住到-sc」" aria-label="Permalink to &quot;LR/SC 不是「总线锁住到 sc」&quot;">​</a></h3><p>现代实现用缓存保留，干涉可能来自一致性失效或异常。过于复杂的保留窗口里插太多指令，实现允许 <code>sc</code> 一直失败（前进保证是架构约束）。把 LR/SC 当关中断的临界区，多核仍会打架。</p><p><span class="marginnote">常见误区：初学者容易把 ABA 当罕见边角。其实很常见：指针 A→B→A 绕一圈回来，CAS 看到的「旧值」没变，底层对象却已被释放复用，无锁栈因此可能悄悄坏链。通用对策是带版本号的标签指针，或改用 LR/SC 的保留语义。</span></p><p><span class="marginnote">RISC-V <code>A</code> 扩展；ARM 独占监视器；Intel <code>cmpxchg</code>。Herlihy/Shavit 给无锁算法背景。本课不写完整 C++ memory_order 表——下一课 fence。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自旋锁：CAS 把 0 改 1。无锁栈：CAS 改头指针。RISC-V：<code>lr.w; 改寄存器; sc.w</code> 循环。ARM：<code>ldaxr/stlxr</code> 带获取/释放变体。失败开销：缓存行来回，与 <a href="/cs/row-buffer-bank-conflict">DRAM</a> 无关但与一致性流量有关。</p>',13)),(A(),l(c,null,{default:r(()=>[t(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAS%5B%22CAS%20%E6%AF%94%E8%BE%83%E5%86%99%22%5D%20--%3E%20RETRY%5B%22%E5%A4%B1%E8%B4%A5%E9%87%8D%E8%AF%95%22%5D%0A%20%20LRSC%5B%22LR%20%E4%BF%9D%E7%95%99%20%2F%20SC%20%E6%9D%A1%E4%BB%B6%E5%86%99%22%5D%20--%3E%20RETRY%0A%20%20AMO%5B%22AMO%20%E5%8D%95%E6%8C%87%E4%BB%A4%20RMW%22%5D%20--%3E%20LOCK%5B%22%E9%94%81%E4%B8%8E%E6%97%A0%E9%94%81%E5%8E%9F%E8%AF%AD%22%5D%0A%20%20RETRY%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BA%8F%E8%BF%98%E8%A6%81%20fence%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"I/O 设备寄存器通常不可用 CAS 当锁，除非规范说可以；MMIO 副作用不同。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：自旋锁就是 \\(\\mathrm{cas}(\\&lock, 0, 1)\\)——初值 0 表空闲，成功者把锁改成 1 进临界区，其余线程反复 CAS 失败原地自旋。失败越多，这根缓存行在核间来回失效的次数越多；争用激烈时吞吐骤降，故自旋锁只适合极短的临界区。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[o("下一课内存序：原子指令往往自带 acquire/release 变体，普通 store 仍可重排。本课只钉「不可分割的读改写」。微码 x86 "),e("code",null,"lock"),o(" 前缀让那条指令的 μop 带锁前缀语义。")],-1)),(A(),l(c,null,{default:r(()=>[t(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRY%5B%22%E8%AF%BB%E5%87%BA%E6%97%A7%E5%80%BC%20old%EF%BC%8C%E7%AE%97%E6%96%B0%E5%80%BC%20new%22%5D%20--%3E%20CAS%5B%22CAS%3A%20%E5%80%BC%E4%BB%8D%E4%B8%BA%20old%20%E6%89%8D%E5%86%99%E5%85%A5%22%5D%0A%20%20CAS%20--%3E%7C%22%E6%88%90%E5%8A%9F%22%7C%20DONE%5B%22%E5%AE%8C%E6%88%90%22%5D%0A%20%20CAS%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%3A%20%E6%9C%89%E4%BA%BA%E6%8A%A2%E5%85%88%22%7C%20TRY%0A%20%20LR%5B%22lr%3A%20%E8%AF%BB%E5%85%A5%E5%B9%B6%E7%99%BB%E8%AE%B0%E4%BF%9D%E7%95%99%22%5D%20--%3E%20MOD%5B%22%E5%9C%A8%E5%AF%84%E5%AD%98%E5%99%A8%E5%89%AF%E6%9C%AC%E4%B8%8A%E6%94%B9%22%5D%20--%3E%20SC%5B%22sc%3A%20%E4%BF%9D%E7%95%99%E6%9C%AA%E7%A0%B4%E6%89%8D%E5%86%99%E5%9B%9E%22%5D%0A%20%20SC%20--%3E%7C%22%E6%88%90%E5%8A%9F%22%7C%20DONE%0A%20%20SC%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%3A%20%E4%BF%9D%E7%95%99%E8%A2%AB%E6%89%93%E7%A0%B4%22%7C%20LR%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明线性一致性全部定理，不把 STM 写进来。不讨论 GPU atomics 的作用域。不进入交易所撮合——禁止限价簿。</p><p>后课默认：多核同步用 CAS 或 LR/SC（及 AMO）；失败重试；ABA 要额外设计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CAS 一次比较并写；LR/SC 两拍保留。</li><li>实现靠缓存排他，不是关中断。</li><li>成功仍可能需要 fence 才能看见数据。</li><li>出处：RISC-V ISA；ARM ARM；Intel SDM；Herlihy and Shavit。</li></ul>',5))])}const f=d(C,[["render",S]]);export{u as __pageData,f as default};
